def kwnames(call):
    return {k.arg for k in call.keywords if k.arg}

# ---- detectors -------------------------------------------------------------
def d_sort_key(src, t):
    for n in walk(t):
        if isinstance(n, ast.Call):
            f = n.func
            if isinstance(f, ast.Name) and f.id == 'sorted' and 'key' in kwnames(n):
                return True
            if isinstance(f, ast.Attribute) and f.attr == 'sort' and 'key' in kwnames(n):
                return True
    return False

def d_sort_any(src, t):
    for n in walk(t):
        if isinstance(n, ast.Call):
            f = n.func
            if isinstance(f, ast.Name) and f.id == 'sorted': return True
            if isinstance(f, ast.Attribute) and f.attr == 'sort': return True
    return False

