import re
def specs_of(t):
    out=[]
    for n in ast.walk(t):
        if isinstance(n,ast.FormattedValue) and n.format_spec is not None:
            js=n.format_spec
            if isinstance(js,ast.JoinedStr):
                s="".join(p.value for p in js.values if isinstance(p,ast.Constant))
                out.append(s)
        if isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute) and n.func.attr=="format" \
           and isinstance(n.func.value,ast.Constant) and isinstance(n.func.value.value,str):
            for m in re.finditer(r"\{[^{}]*\}", n.func.value.value):
                f=m.group(0)
                if ":" in f: out.append(f.split(":",1)[1][:-1])
        if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id=="format" and len(n.args)>=2:
            a=n.args[1]
            if isinstance(a,ast.Constant) and isinstance(a.value,str): out.append(a.value)
    return out
